/* ========================================
   WellStream Platform — Global Styles
   ======================================== */

:root {
  --color-bg-primary: #0D1B2A;
  --color-bg-secondary: #1B2838;
  --color-bg-tertiary: #15295A;
  --color-accent: #00B4D8;
  --color-accent-hover: #0077B6;
  --color-accent-green: #6CC24A;
  --color-text-primary: #E0E6ED;
  --color-text-secondary: #8FA3B8;
  --color-text-muted: #5C7088;
  --color-border: #2A3F55;
  --color-card-bg: #132238;
  --color-input-bg: #0F1D2E;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --transition-fast: 0.2s ease;
  --transition-medium: 0.35s ease;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.25);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.35);
  --shadow-lg: 0 16px 48px rgba(0,0,0,0.45);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-accent-hover);
}

img {
  max-width: 100%;
  display: block;
}

/* ========================================
   Typography
   ======================================== */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-text-primary);
}

h1 { font-size: clamp(2rem, 4vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.1rem, 2vw, 1.5rem); }
h4 { font-size: 1.1rem; }

p {
  color: var(--color-text-secondary);
  font-size: 1rem;
}

.text-accent { color: var(--color-accent); }
.text-green { color: var(--color-accent-green); }
.text-muted { color: var(--color-text-muted); }

.label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent);
}

/* ========================================
   Layout Utilities
   ======================================== */

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-sm {
  padding: 48px 0;
}

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-between {
  justify-content: space-between;
}

.justify-center {
  justify-content: center;
}

.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }

.grid {
  display: grid;
}

.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
.grid-cols-6 { grid-template-columns: repeat(6, 1fr); }

.text-center { text-align: center; }

/* ========================================
   Buttons
   ======================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-hover));
  color: #fff;
  box-shadow: 0 4px 16px rgba(0, 180, 216, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(0, 180, 216, 0.45);
  color: #fff;
}

.btn-secondary {
  background: transparent;
  color: var(--color-text-primary);
  border: 1.5px solid var(--color-border);
}

.btn-secondary:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
  transform: translateY(-2px);
}

.btn-green {
  background: linear-gradient(135deg, var(--color-accent-green), #4a9e2d);
  color: #fff;
  box-shadow: 0 4px 16px rgba(108, 194, 74, 0.3);
}

.btn-green:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(108, 194, 74, 0.45);
  color: #fff;
}

/* ========================================
   Header & Navigation
   ======================================== */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--color-text-primary);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--color-accent);
}

.nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover {
  color: var(--color-text-primary);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px 0;
}

.nav-dropdown-toggle:hover {
  color: var(--color-text-primary);
}

.nav-dropdown-toggle svg {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-toggle svg {
  transform: rotate(180deg);
}

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 8px 0;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all var(--transition-fast);
  box-shadow: var(--shadow-md);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: 10px 20px;
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
}

.nav-dropdown-menu a:hover {
  background: rgba(0, 180, 216, 0.08);
  color: var(--color-accent);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--color-text-primary);
  cursor: pointer;
  padding: 8px;
}

/* ========================================
   Hero
   ======================================== */

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding-top: 72px;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(0, 119, 182, 0.15) 0%, transparent 60%),
              radial-gradient(ellipse at 80% 80%, rgba(0, 180, 216, 0.08) 0%, transparent 50%),
              var(--color-bg-primary);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image: 
    linear-gradient(rgba(42, 63, 85, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(42, 63, 85, 0.15) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 70%);
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: 0 24px;
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--color-text-secondary);
  margin-bottom: 40px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ========================================
   Cards
   ======================================== */

.card {
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 32px;
  transition: all var(--transition-medium);
}

.card:hover {
  border-color: rgba(0, 180, 216, 0.3);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(0, 180, 216, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.card-icon svg {
  width: 24px;
  height: 24px;
  color: var(--color-accent);
}

.card-title {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.card-text {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ========================================
   Tabs
   ======================================== */

.tabs {
  display: flex;
  gap: 4px;
  background: var(--color-bg-secondary);
  border-radius: 8px;
  padding: 4px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 20px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--color-text-primary);
}

.tab-btn.active {
  background: var(--color-accent);
  color: #fff;
}

.tab-panel {
  display: none;
  animation: fadeIn 0.35s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========================================
   Accordion
   ======================================== */

.accordion-item {
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.accordion-item:hover {
  border-color: rgba(0, 180, 216, 0.2);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  color: var(--color-text-primary);
  font-size: 1.05rem;
  font-weight: 600;
  transition: background var(--transition-fast);
}

.accordion-header:hover {
  background: rgba(0, 180, 216, 0.04);
}

.accordion-header svg {
  width: 20px;
  height: 20px;
  color: var(--color-accent);
  transition: transform var(--transition-fast);
  flex-shrink: 0;
}

.accordion-item.open .accordion-header svg {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-medium), padding var(--transition-medium);
}

.accordion-item.open .accordion-body {
  max-height: 300px;
  padding: 0 24px 20px;
}

.accordion-body p {
  color: var(--color-text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ========================================
   Stats
   ======================================== */

.stat-circle {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  background: conic-gradient(var(--color-accent) var(--progress), var(--color-border) var(--progress));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  margin: 0 auto 20px;
}

.stat-circle::before {
  content: '';
  position: absolute;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: var(--color-bg-primary);
}

.stat-circle-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.stat-value {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--color-text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-top: 6px;
}

/* ========================================
   Progress Bars
   ======================================== */

.progress-item {
  margin-bottom: 28px;
}

.progress-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
}

.progress-title {
  font-weight: 600;
  color: var(--color-text-primary);
}

.progress-time {
  font-weight: 700;
  color: var(--color-accent);
}

.progress-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: 4px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-accent), var(--color-accent-hover));
  border-radius: 4px;
  transition: width 1s ease;
}

/* ========================================
   Testimonials
   ======================================== */

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 12px;
}

.testimonial-card {
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 40px;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  font-style: italic;
  color: var(--color-text-primary);
  margin-bottom: 20px;
  line-height: 1.7;
}

.testimonial-author {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-accent);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 28px;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.testimonial-dot.active {
  background: var(--color-accent);
  transform: scale(1.2);
}

/* ========================================
   Forms
   ======================================== */

.form-group {
  margin-bottom: 20px;
}

.form-label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 12px 16px;
  font-size: 0.95rem;
  font-family: var(--font-family);
  color: var(--color-text-primary);
  background: var(--color-input-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.1);
}

.form-input::placeholder,
.form-textarea::placeholder {
  color: var(--color-text-muted);
}

.form-textarea {
  resize: vertical;
  min-height: 120px;
}

.form-error {
  font-size: 0.8rem;
  color: #e74c3c;
  margin-top: 6px;
  display: none;
}

.form-group.has-error .form-input,
.form-group.has-error .form-select,
.form-group.has-error .form-textarea {
  border-color: #e74c3c;
}

.form-group.has-error .form-error {
  display: block;
}

/* ========================================
   Cookie Banner
   ======================================== */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  padding: 20px 0;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-text {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
}

.cookie-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

/* ========================================
   Footer
   ======================================== */

.footer {
  background: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col-title {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-muted);
  margin-bottom: 20px;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: 10px;
}

.footer-links a {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  border-top: 1px solid var(--color-border);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copyright {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.footer-portals {
  display: flex;
  gap: 20px;
}

.footer-portals a {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.footer-portals a:hover {
  color: var(--color-accent);
}

/* ========================================
   Diagrams
   ======================================== */

.diagram-container {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 40px 0;
}

.pillar-diagram {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
}

.pillar {
  width: 280px;
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 32px;
  text-align: center;
  position: relative;
  transition: all var(--transition-medium);
}

.pillar:hover {
  border-color: var(--color-accent);
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.pillar-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(0, 180, 216, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.pillar-icon svg {
  width: 28px;
  height: 28px;
  color: var(--color-accent);
}

.pillar-title {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.pillar-desc {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.pillar-connector {
  display: none;
}

/* ========================================
   Data Lifecycle Diagram
   ======================================== */

.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 900px;
  margin: 0 auto;
}

.lifecycle-row {
  display: flex;
  align-items: center;
  gap: 16px;
}

.lifecycle-node {
  flex: 1;
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  padding: 20px 24px;
  text-align: center;
  font-weight: 600;
  font-size: 0.95rem;
  transition: all var(--transition-fast);
}

.lifecycle-node:hover {
  border-color: var(--color-accent);
  background: rgba(0, 180, 216, 0.05);
}

.lifecycle-arrow {
  color: var(--color-accent);
  font-size: 1.2rem;
  flex-shrink: 0;
}

/* ========================================
   Feature List
   ======================================== */

.feature-list {
  list-style: none;
}

.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 20px 0;
  border-bottom: 1px solid var(--color-border);
}

.feature-list-item:last-child {
  border-bottom: none;
}

.feature-list-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: rgba(0, 180, 216, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.feature-list-icon svg {
  width: 20px;
  height: 20px;
  color: var(--color-accent);
}

.feature-list-content h4 {
  font-size: 1.05rem;
  margin-bottom: 6px;
}

.feature-list-content p {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
}

/* ========================================
   Banner
   ======================================== */

.banner {
  background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-bg-secondary));
  border: 1px solid var(--color-border);
  border-radius: 12px;
